    /**
     * Image path for an Unsplash photo id. Images are stored locally in
     * public/images/library (run `php artisan images:localize` after seeding if
     * the files are missing; it downloads anything still remote).
     */
    public static function u(string $id, int $w = 1600): string
    {
        $local = '/images/library/photo-'.$id.'.jpg';
        if (file_exists(public_path($local))) {
            return $local;
        }

        return "https://images.unsplash.com/photo-{$id}?w={$w}&q=80&auto=format&fit=crop";
    }

