    /** Build gallery images for the i-th design from the verified photo pool. */
    public static function images(int $index, int $count, array $design): array
    {
        $n = count(self::PHOTO_POOL);
        $images = [];
        for ($k = 0; $k < $count; $k++) {
            $id = self::PHOTO_POOL[($index * 3 + $k * 7) % $n];
            [$angle, $title, $desc] = self::ANGLES[$k % count(self::ANGLES)];
            $images[] = [
                'url' => self::u($id),
                'angle' => $angle,
                'title' => $title.' · '.$design['title'],
                'description' => $desc.' '.$design['summary'],
            ];
        }

        return $images;
    }
}
